
export const APP_PY_CODE = "\"\"\"\nHOUSE PRICE PREDICTION USING LINEAR REGRESSION\nCollege Major Project (BCA / B.Tech Computer Science)\n\nThis Streamlit application trains a Multiple Linear Regression model\non the house_prices.csv dataset to predict estimated house prices.\n\"\"\"\n\nimport streamlit as st\nimport pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\nimport seaborn as sns\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.metrics import mean_squared_error, r2_score, mean_absolute_error\nimport os\n\n# Set Matplotlib aesthetic style\nplt.style.use('seaborn-v0_8-whitegrid' if 'seaborn-v0_8-whitegrid' in plt.style.available else 'default')\nplt.rcParams['font.sans-serif'] = 'DejaVu Sans'\n\n# -------------------------------------------------------------\n# PAGE CONFIGURATION\n# -------------------------------------------------------------\nst.set_page_config(\n    page_title=\"House Price Prediction - Linear Regression\",\n    page_icon=\"\ud83c\udfe0\",\n    layout=\"wide\",\n    initial_sidebar_state=\"expanded\"\n)\n\n# -------------------------------------------------------------\n# HELPER FUNCTIONS & DATA PIPELINE\n# -------------------------------------------------------------\n\n@st.cache_data\ndef load_and_preprocess_data(csv_path=\"house_prices.csv\"):\n    \"\"\"\n    Module 1 & 2: Dataset Collection & Data Preprocessing\n    Loads the CSV dataset, removes duplicates, handles missing values,\n    and returns a cleaned Pandas DataFrame.\n    \"\"\"\n    if not os.path.exists(csv_path):\n        st.error(f\"Dataset file '{csv_path}' not found! Please ensure it is in the project root directory.\")\n        return None\n    \n    df = pd.read_csv(csv_path)\n    \n    # Check and remove duplicates\n    df = df.drop_duplicates()\n    \n    # Handle missing values if any\n    num_cols = df.select_dtypes(include=[np.number]).columns\n    for col in num_cols:\n        if df[col].isnull().sum() > 0:\n            df[col] = df[col].fillna(df[col].median())\n            \n    return df\n\n\n@st.cache_resource\ndef train_linear_regression_model(df, test_size=0.2, random_state=42):\n    \"\"\"\n    Module 4, 5 & 6: Feature Selection, Model Building & Training\n    Uses scikit-learn Pipeline with StandardScaler and LinearRegression.\n    \"\"\"\n    feature_cols = [\n        'Area_sqft', 'Bedrooms', 'Bathrooms', 'Floors',\n        'Parking', 'Age', 'Location_Score', 'Distance_to_City_km'\n    ]\n    target_col = 'House_Price'\n    \n    X = df[feature_cols]\n    y = df[target_col]\n    \n    # Split dataset into Training and Testing sets\n    X_train, X_test, y_train, y_test = train_test_split(\n        X, y, test_size=test_size, random_state=random_state\n    )\n    \n    # Create Pipeline with Feature Scaler and Linear Regression model\n    pipeline = Pipeline([\n        ('scaler', StandardScaler()),\n        ('regressor', LinearRegression())\n    ])\n    \n    # Fit model on training data\n    pipeline.fit(X_train, y_train)\n    \n    # Predictions for evaluation\n    y_train_pred = pipeline.predict(X_train)\n    y_test_pred = pipeline.predict(X_test)\n    \n    # Evaluation Metrics\n    mse_test = mean_squared_error(y_test, y_test_pred)\n    rmse_test = np.sqrt(mse_test)\n    mae_test = mean_absolute_error(y_test, y_test_pred)\n    r2_test = r2_score(y_test, y_test_pred)\n    \n    # Extract coefficients\n    raw_model = pipeline.named_steps['regressor']\n    coefficients = raw_model.coef_\n    intercept = raw_model.intercept_\n    \n    # Unscaled coefficients for direct linear interpretation:\n    # y = Intercept_unscaled + sum(coeff_unscaled_i * X_i)\n    unscaled_model = LinearRegression()\n    unscaled_model.fit(X_train, y_train)\n    \n    results = {\n        'pipeline': pipeline,\n        'unscaled_model': unscaled_model,\n        'feature_cols': feature_cols,\n        'X_train': X_train,\n        'X_test': X_test,\n        'y_train': y_train,\n        'y_test': y_test,\n        'y_test_pred': y_test_pred,\n        'mse': mse_test,\n        'rmse': rmse_test,\n        'mae': mae_test,\n        'r2': r2_test,\n        'scaled_coef': coefficients,\n        'intercept': intercept,\n        'unscaled_coef': unscaled_model.coef_,\n        'unscaled_intercept': unscaled_model.intercept_\n    }\n    return results\n\n\ndef format_inr(number):\n    \"\"\"Formats a number into Indian Rupee numbering format (\u20b9XX,XX,XXX)\"\"\"\n    num_int = int(round(number))\n    if num_int < 0:\n        return f\"-\u20b9{abs(num_int):,}\"\n    \n    s = str(num_int)\n    if len(s) <= 3:\n        return f\"\u20b9{s}\"\n    last_three = s[-3:]\n    remaining = s[:-3]\n    \n    # Group remaining digits in sets of 2\n    groups = []\n    while len(remaining) > 2:\n        groups.insert(0, remaining[-2:])\n        remaining = remaining[:-2]\n    if remaining:\n        groups.insert(0, remaining)\n    \n    formatted = \",\".join(groups) + \",\" + last_three\n    return f\"\u20b9{formatted}\"\n\n\n# -------------------------------------------------------------\n# LOAD DATA & MODEL\n# -------------------------------------------------------------\ndf = load_and_preprocess_data()\n\nif df is not None:\n    model_data = train_linear_regression_model(df)\nelse:\n    st.stop()\n\n\n# -------------------------------------------------------------\n# SIDEBAR NAVIGATION\n# -------------------------------------------------------------\nst.sidebar.image(\"https://img.icons8.com/isometric/100/real-estate.png\", width=80)\nst.sidebar.title(\"House Price Prediction\")\nst.sidebar.markdown(\"**Major Project - BCA / CS**\")\nst.sidebar.markdown(\"---\")\n\nnavigation = st.sidebar.radio(\n    \"Navigation Menu\",\n    [\n        \"1. \ud83c\udfe0 HOME\",\n        \"2. \ud83d\udcca DATASET\",\n        \"3. \ud83d\udcc8 DATA ANALYSIS\",\n        \"4. \ud83e\udde0 MODEL\",\n        \"5. \ud83d\udcb0 PRICE PREDICTION\",\n        \"6. \u2139\ufe0f ABOUT PROJECT\"\n    ]\n)\n\nst.sidebar.markdown(\"---\")\nst.sidebar.markdown(f\"**Model R\u00b2 Score:** `{model_data['r2']:.4f}`\")\nst.sidebar.markdown(f\"**Total Records:** `{len(df)} rows`\")\nst.sidebar.caption(\"Supervised Machine Learning \u2022 Linear Regression\")\n\n\n# =============================================================\n# 1. HOME SECTION\n# =============================================================\nif navigation == \"1. \ud83c\udfe0 HOME\":\n    st.title(\"\ud83c\udfe0 HOUSE PRICE PREDICTION USING LINEAR REGRESSION\")\n    st.subheader(\"A Machine Learning Project for Real Estate Valuation\")\n    st.markdown(\"---\")\n    \n    col1, col2 = st.columns([3, 2])\n    \n    with col1:\n        st.markdown(\"\"\"\n        ### \ud83d\udccc Project Overview\n        House price prediction is a classic **Supervised Machine Learning** regression problem.\n        The goal of this project is to develop an automated predictive system that estimates the \n        monetary market value of residential properties using their architectural, spatial, and locational features.\n        \n        ### \ud83c\udfaf Project Objectives\n        1. **Data Preprocessing & Cleaning**: Collect and sanitize multi-feature real estate records.\n        2. **Exploratory Data Analysis (EDA)**: Uncover correlations between house price and features such as area, bedrooms, and location score.\n        3. **Model Construction**: Implement the **Ordinary Least Squares (OLS) Linear Regression** algorithm using `scikit-learn`.\n        4. **Model Evaluation**: Benchmark the model against test data using **Mean Squared Error (MSE)** and **Coefficient of Determination ($R^2$)**.\n        5. **Interactive Prediction Interface**: Allow users to enter customized house details and receive an immediate, mathematically sound price estimate in Indian Rupees (\u20b9).\n        \"\"\")\n        \n    with col2:\n        st.info(\"\"\"\n        ### \u2699\ufe0f How the System Works\n        ```\n        1. Raw House Dataset (CSV)\n                \u2b07\n        2. Preprocessing & Scaling (StandardScaler)\n                \u2b07\n        3. Train-Test Split (80/20)\n                \u2b07\n        4. Linear Regression Model Training\n                \u2b07\n        5. User Input Features\n                \u2b07\n        6. Estimated Price (\u20b9XX,XX,XXX)\n        ```\n        \"\"\")\n        \n    st.markdown(\"---\")\n    st.markdown(\"### \ud83c\udfc6 Key Project Performance Highlights\")\n    m1, m2, m3, m4 = st.columns(4)\n    m1.metric(\"Dataset Size\", f\"{len(df)} Records\", \"8 Features\")\n    m2.metric(\"Model R\u00b2 Score\", f\"{model_data['r2'] * 100:.2f}%\", \"Variance Explained\")\n    m3.metric(\"Root Mean Squared Error\", format_inr(model_data['rmse']), \"Average Deviation\")\n    m4.metric(\"Mean Absolute Error\", format_inr(model_data['mae']), \"L1 Loss\")\n\n\n# =============================================================\n# 2. DATASET SECTION\n# =============================================================\nelif navigation == \"2. \ud83d\udcca DATASET\":\n    st.title(\"\ud83d\udcca Dataset Exploration & Preprocessing\")\n    st.write(\"Demonstration real-estate dataset (`house_prices.csv`) utilized for training the Linear Regression model.\")\n    st.markdown(\"---\")\n    \n    col1, col2, col3, col4 = st.columns(4)\n    col1.metric(\"Total Rows\", df.shape[0])\n    col2.metric(\"Total Columns\", df.shape[1])\n    col3.metric(\"Numerical Features\", 8)\n    col4.metric(\"Target Variable\", \"House_Price\")\n    \n    st.markdown(\"### \ud83d\udccb Dataset Preview (Top 10 Records)\")\n    st.dataframe(df.head(10), use_container_width=True)\n    \n    st.markdown(\"### \ud83d\udd0d Feature Descriptions & Data Types\")\n    feature_info = pd.DataFrame({\n        \"Feature Name\": df.columns,\n        \"Data Type\": df.dtypes.astype(str),\n        \"Non-Null Count\": df.notnull().sum(),\n        \"Missing Values\": df.isnull().sum(),\n        \"Description\": [\n            \"Total carpet and built-up area in square feet\",\n            \"Total number of bedrooms in the property\",\n            \"Total number of bathrooms in the property\",\n            \"Total number of floors/stories\",\n            \"Reserved vehicle parking spots\",\n            \"Age of the construction in years\",\n            \"Civic infrastructure & locality score (1.0 to 10.0)\",\n            \"Road distance from central city hub in kilometers\",\n            \"Final valuation price of the property in INR (\u20b9) [Target]\"\n        ]\n    })\n    st.table(feature_info)\n    \n    st.markdown(\"### \ud83d\udcc8 Statistical Summary (Pandas .describe())\")\n    st.dataframe(df.describe().T, use_container_width=True)\n    \n    st.info(\"\ud83d\udca1 **Demonstration Dataset Note:** This dataset contains representative real estate records engineered for demonstration. In production environments, real-world registry or MLS datasets can be substituted directly.\")\n\n\n# =============================================================\n# 3. DATA ANALYSIS SECTION\n# =============================================================\nelif navigation == \"3. \ud83d\udcc8 DATA ANALYSIS\":\n    st.title(\"\ud83d\udcc8 Exploratory Data Analysis (EDA)\")\n    st.write(\"Visual examination of feature distributions, multi-collinearity, and relationships with House Price.\")\n    st.markdown(\"---\")\n    \n    col1, col2 = st.columns(2)\n    \n    with col1:\n        st.subheader(\"1. House Price Distribution\")\n        fig1, ax1 = plt.subplots(figsize=(7, 4.5))\n        sns.histplot(df['House_Price'] / 1e5, kde=True, color='#2563EB', ax=ax1, bins=25)\n        ax1.set_xlabel(\"House Price (in Lakhs \u20b9)\")\n        ax1.set_ylabel(\"Frequency\")\n        ax1.set_title(\"Distribution of Property Prices\")\n        st.pyplot(fig1)\n        \n    with col2:\n        st.subheader(\"2. Area (sqft) vs House Price\")\n        fig2, ax2 = plt.subplots(figsize=(7, 4.5))\n        sns.regplot(\n            data=df, x='Area_sqft', y=df['House_Price'] / 1e5,\n            scatter_kws={'alpha': 0.5, 'color': '#059669'},\n            line_kws={'color': '#DC2626', 'linewidth': 2},\n            ax=ax2\n        )\n        ax2.set_xlabel(\"Area in Square Feet\")\n        ax2.set_ylabel(\"House Price (in Lakhs \u20b9)\")\n        ax2.set_title(\"Scatter Plot with Linear Regression Trendline\")\n        st.pyplot(fig2)\n        \n    st.markdown(\"---\")\n    col3, col4 = st.columns(2)\n    \n    with col3:\n        st.subheader(\"3. Bedrooms vs House Price\")\n        fig3, ax3 = plt.subplots(figsize=(7, 4.5))\n        sns.boxplot(x='Bedrooms', y=df['House_Price'] / 1e5, data=df, palette='Blues', ax=ax3)\n        ax3.set_xlabel(\"Number of Bedrooms\")\n        ax3.set_ylabel(\"House Price (in Lakhs \u20b9)\")\n        ax3.set_title(\"Price Distribution Across Bedroom Counts\")\n        st.pyplot(fig3)\n        \n    with col4:\n        st.subheader(\"4. Correlation Matrix Heatmap\")\n        fig4, ax4 = plt.subplots(figsize=(7, 4.5))\n        corr = df.corr()\n        sns.heatmap(corr, annot=True, fmt=\".2f\", cmap='coolwarm', cbar=True, ax=ax4, square=True)\n        ax4.set_title(\"Pearson Correlation Heatmap\")\n        st.pyplot(fig4)\n        \n    st.markdown(\"---\")\n    st.subheader(\"5. Location Score vs Distance to City Analysis\")\n    fig5, ax5 = plt.subplots(figsize=(10, 4))\n    scatter = ax5.scatter(\n        df['Distance_to_City_km'], df['House_Price'] / 1e5,\n        c=df['Location_Score'], cmap='viridis', alpha=0.75, s=df['Area_sqft'] / 40\n    )\n    ax5.set_xlabel(\"Distance to City (km)\")\n    ax5.set_ylabel(\"House Price (in Lakhs \u20b9)\")\n    ax5.set_title(\"Distance vs Price (Color = Location Score, Size = Area)\")\n    cbar = plt.colorbar(scatter, ax=ax5)\n    cbar.set_label(\"Location Score (1 - 10)\")\n    st.pyplot(fig5)\n\n\n# =============================================================\n# 4. MODEL SECTION\n# =============================================================\nelif navigation == \"4. \ud83e\udde0 MODEL\":\n    st.title(\"\ud83e\udde0 Linear Regression Model Evaluation\")\n    st.write(\"Mathematical details, train/test metrics, regression coefficients, and diagnostic residual plots.\")\n    st.markdown(\"---\")\n    \n    st.markdown(\"\"\"\n    ### \ud83d\udcd0 Mathematical Formulation\n    Multiple Linear Regression models the relationship between dependent variable ($Y$) and independent features ($X_1, X_2, \\dots, X_n$):\n    $$Y = \\\\beta_0 + \\\\beta_1 X_1 + \\\\beta_2 X_2 + \\\\dots + \\\\beta_n X_n + \\\\epsilon$$\n    Where:\n    - $Y$: Target variable (`House_Price`)\n    - $\\\\beta_0$: Intercept (base price when all features are zero)\n    - $\\\\beta_i$: Regression coefficient for feature $i$\n    - $\\\\epsilon$: Residual error term\n    \"\"\")\n    \n    st.markdown(\"### \ud83d\udcca Performance Metrics on Test Set (20% Holdout)\")\n    m1, m2, m3, m4 = st.columns(4)\n    m1.metric(\"R\u00b2 Score (Coefficient of Determination)\", f\"{model_data['r2']:.4f}\")\n    m2.metric(\"Mean Squared Error (MSE)\", f\"{model_data['mse']:,.0f}\")\n    m3.metric(\"Root Mean Squared Error (RMSE)\", format_inr(model_data['rmse']))\n    m4.metric(\"Mean Absolute Error (MAE)\", format_inr(model_data['mae']))\n    \n    st.markdown(\"### \ud83d\udccb Learned Regression Coefficients\")\n    coef_df = pd.DataFrame({\n        \"Feature\": model_data['feature_cols'],\n        \"Unscaled Coefficient (\u20b9 / unit)\": model_data['unscaled_coef'],\n        \"Standardized Coefficient\": model_data['scaled_coef'],\n        \"Interpretation\": [\n            \"For every 1 sqft increase, price increases by ~\u20b9\" + f\"{int(model_data['unscaled_coef'][0]):,}\",\n            \"Each additional bedroom adds ~\u20b9\" + f\"{int(model_data['unscaled_coef'][1]):,}\",\n            \"Each additional bathroom adds ~\u20b9\" + f\"{int(model_data['unscaled_coef'][2]):,}\",\n            \"Each additional floor adds ~\u20b9\" + f\"{int(model_data['unscaled_coef'][3]):,}\",\n            \"Each parking slot adds ~\u20b9\" + f\"{int(model_data['unscaled_coef'][4]):,}\",\n            \"Each year of property age reduces price by ~\u20b9\" + f\"{abs(int(model_data['unscaled_coef'][5])):,}\",\n            \"Each 1.0 point in Location Score increases price by ~\u20b9\" + f\"{int(model_data['unscaled_coef'][6]):,}\",\n            \"Each km away from city reduces price by ~\u20b9\" + f\"{abs(int(model_data['unscaled_coef'][7])):,}\"\n        ]\n    })\n    st.dataframe(coef_df, use_container_width=True)\n    st.write(f\"**Model Intercept (\\\\beta_0):** `{format_inr(model_data['unscaled_intercept'])}`\")\n    \n    st.markdown(\"---\")\n    st.subheader(\"\ud83d\udd0d Actual vs Predicted Prices Scatter Plot\")\n    fig, ax = plt.subplots(figsize=(8, 5))\n    ax.scatter(model_data['y_test'] / 1e5, model_data['y_test_pred'] / 1e5, color='#2563EB', alpha=0.6, label='Predictions')\n    # Ideal fit diagonal line\n    min_val = min(model_data['y_test'].min(), model_data['y_test_pred'].min()) / 1e5\n    max_val = max(model_data['y_test'].max(), model_data['y_test_pred'].max()) / 1e5\n    ax.plot([min_val, max_val], [min_val, max_val], 'r--', lw=2, label='Perfect Fit (y = x)')\n    ax.set_xlabel(\"Actual House Price (in Lakhs \u20b9)\")\n    ax.set_ylabel(\"Predicted House Price (in Lakhs \u20b9)\")\n    ax.set_title(f\"Actual vs Predicted Prices (R\u00b2 = {model_data['r2']:.4f})\")\n    ax.legend()\n    st.pyplot(fig)\n\n\n# =============================================================\n# 5. PRICE PREDICTION SECTION\n# =============================================================\nelif navigation == \"5. \ud83d\udcb0 PRICE PREDICTION\":\n    st.title(\"\ud83d\udcb0 Real Estate Price Prediction\")\n    st.write(\"Enter house specifications below to compute the estimated market price using the trained Linear Regression pipeline.\")\n    st.markdown(\"---\")\n    \n    with st.form(\"prediction_form\"):\n        col1, col2 = st.columns(2)\n        \n        with col1:\n            st.markdown(\"#### \ud83d\udcd0 Structural Specifications\")\n            area = st.number_input(\"Area in Square Feet (Area_sqft)\", min_value=300, max_value=8000, value=1850, step=50)\n            bedrooms = st.slider(\"Number of Bedrooms\", min_value=1, max_value=8, value=3, step=1)\n            bathrooms = st.slider(\"Number of Bathrooms\", min_value=1, max_value=6, value=2, step=1)\n            floors = st.slider(\"Number of Floors\", min_value=1, max_value=5, value=2, step=1)\n            \n        with col2:\n            st.markdown(\"#### \ud83d\udccd Locality & Property Age\")\n            parking = st.slider(\"Parking Spaces\", min_value=0, max_value=4, value=1, step=1)\n            age = st.slider(\"Age of House in Years\", min_value=0, max_value=50, value=5, step=1)\n            location_score = st.slider(\"Location Score (1.0 = Rural / Basic, 10.0 = Prime Urban)\", min_value=1.0, max_value=10.0, value=7.5, step=0.1)\n            distance = st.number_input(\"Distance to City Center in km\", min_value=0.5, max_value=50.0, value=8.5, step=0.5)\n            \n        st.markdown(\"---\")\n        submit_button = st.form_submit_button(\"\ud83d\udd2e PREDICT HOUSE PRICE\", use_container_width=True)\n        \n    if submit_button:\n        # Assemble input DataFrame\n        user_input_df = pd.DataFrame([{\n            'Area_sqft': area,\n            'Bedrooms': bedrooms,\n            'Bathrooms': bathrooms,\n            'Floors': floors,\n            'Parking': parking,\n            'Age': age,\n            'Location_Score': location_score,\n            'Distance_to_City_km': distance\n        }])\n        \n        # Preprocess using fitted pipeline and predict\n        predicted_price = model_data['pipeline'].predict(user_input_df)[0]\n        \n        # Ensure non-negative price\n        predicted_price = max(0, predicted_price)\n        formatted_price = format_inr(predicted_price)\n        in_lakhs = predicted_price / 100000\n        in_crores = predicted_price / 10000000\n        \n        st.success(f\"### \ud83c\udf89 Estimated House Price: {formatted_price}\")\n        \n        metric_col1, metric_col2, metric_col3 = st.columns(3)\n        metric_col1.metric(\"Predicted Valuation\", formatted_price)\n        metric_col2.metric(\"In Lakhs (\u20b9)\", f\"\u20b9{in_lakhs:.2f} Lakhs\")\n        metric_col3.metric(\"In Crores (\u20b9)\", f\"\u20b9{in_crores:.2f} Cr\" if in_crores >= 1.0 else \"\u2014\")\n        \n        st.markdown(\"#### \ud83e\uddfe Feature Contribution Breakdown\")\n        breakdown_data = []\n        for feat, coef in zip(model_data['feature_cols'], model_data['unscaled_coef']):\n            val = user_input_df[feat].values[0]\n            contrib = val * coef\n            breakdown_data.append({\n                \"Feature\": feat,\n                \"User Value\": val,\n                \"Rate / Unit\": f\"\u20b9{coef:,.0f}\",\n                \"Net Contribution\": f\"\u20b9{contrib:,.0f}\"\n            })\n        \n        b_df = pd.DataFrame(breakdown_data)\n        st.table(b_df)\n        \n        st.warning(\"\u26a0\ufe0f **Disclaimer:** This estimation is produced by a trained Multiple Linear Regression machine learning model for academic demonstration. Actual market prices depend on micro-location factors, legal clearances, negotiated terms, and prevailing real estate market dynamics.\")\n\n\n# =============================================================\n# 6. ABOUT PROJECT SECTION\n# =============================================================\nelif navigation == \"6. \u2139\ufe0f ABOUT PROJECT\":\n    st.title(\"\u2139\ufe0f About the Major Project\")\n    st.markdown(\"---\")\n    \n    st.markdown(\"\"\"\n    ### \ud83c\udf93 Project Identification\n    - **Project Title:** HOUSE PRICE PREDICTION USING LINEAR REGRESSION\n    - **Course:** Bachelor of Computer Applications (BCA) / B.Tech Computer Science\n    - **Domain:** Supervised Machine Learning, Predictive Modeling, Real Estate Analytics\n    - **Primary Algorithm:** Multiple Linear Regression (Ordinary Least Squares - OLS)\n    \n    ---\n    \n    ### \ud83c\udfaf Aim and Objectives\n    The central aim of this project is to eliminate guesswork and subjective speculation in real-estate valuations by creating an objective, algorithmic pricing model.\n    - **Data Pipeline:** Seamless ingest, validation, and normalization of property characteristics.\n    - **Mathematical Precision:** Minimization of residual sum of squares via closed-form OLS normal equations.\n    - **Student-Friendly UI:** Intuitive, transparent presentation of both predictions and underlying mathematical coefficients.\n    \n    ---\n    \n    ### \ud83d\udcbb Technologies & Libraries\n    | Technology | Purpose |\n    | :--- | :--- |\n    | **Python 3.10+** | Core programming language |\n    | **Pandas** | Data wrangling, CSV manipulation, tabular analysis |\n    | **NumPy** | High-performance multi-dimensional array arithmetic |\n    | **Scikit-Learn** | Model training, StandardScaler, train_test_split, evaluation metrics |\n    | **Matplotlib & Seaborn** | Statistical charts, distribution plots, heatmaps, regression lines |\n    | **Streamlit** | Interactive web dashboard and real-time prediction interface |\n    \n    ---\n    \n    ### \u26a0\ufe0f Limitations of Linear Regression\n    1. **Assumes Linearity:** Real estate dynamics can exhibit non-linear inflection points (e.g., luxury threshold multipliers).\n    2. **Outlier Sensitivity:** OLS minimizes squared errors, making it sensitive to extreme price outliers.\n    3. **Multi-Collinearity:** Strong correlation between area and bedrooms requires careful feature inspection.\n    \n    ---\n    \n    ### \ud83d\ude80 Future Enhancements\n    1. **Non-Linear Models:** Integration of Random Forest Regressor and Gradient Boosting (XGBoost).\n    2. **Geographical GIS Integration:** Interactive Google Maps / OpenStreetMap pin-drop for live latitude/longitude geocoding.\n    3. **Time-Series Adjustment:** Incorporating inflation indices and historical price trends.\n    4. **Image-Based Valuation:** Employing Convolutional Neural Networks (CNNs) to evaluate interior property finishes from photos.\n    \"\"\")\n\nst.markdown(\"---\")\nst.caption(\"College Major Project \u2022 House Price Prediction Using Linear Regression \u2022 Developed with Python, Scikit-Learn & Streamlit\")\n";
export const REQUIREMENTS_TXT_CODE = "streamlit>=1.30.0\npandas>=2.0.0\nnumpy>=1.24.0\nscikit-learn>=1.3.0\nmatplotlib>=3.7.0\nseaborn>=0.12.0\n";
export const README_MD_CODE = "# HOUSE PRICE PREDICTION USING LINEAR REGRESSION\n### College Major Project (BCA / B.Sc / B.Tech Computer Science)\n\nAn end-to-end Machine Learning web application designed to predict residential property valuations using Multiple Linear Regression.\n\n---\n\n## \ud83d\udccc Project Overview\nValuing real estate properties is traditionally prone to subjective bias, asymmetry of information, and fluctuating agent commissions. This project implements a **Supervised Machine Learning** pipeline using the **Multiple Linear Regression (Ordinary Least Squares)** algorithm to estimate house prices systematically based on 8 key structural and geographic parameters:\n- **Area (sqft)**\n- **Bedrooms**\n- **Bathrooms**\n- **Floors**\n- **Parking Spaces**\n- **House Age (Years)**\n- **Location Score (1.0 to 10.0)**\n- **Distance to City Center (km)**\n\n---\n\n## \ud83d\udee0\ufe0f Technology Stack\n- **Language:** Python 3.10+\n- **Machine Learning Library:** `scikit-learn` (LinearRegression, StandardScaler, train_test_split, metrics)\n- **Data Manipulation:** `pandas`, `numpy`\n- **Data Visualization:** `matplotlib`, `seaborn`\n- **Web Interface:** `Streamlit` / React SPA interactive dashboard\n- **Dataset:** `house_prices.csv` (650 records)\n\n---\n\n## \ud83d\ude80 How to Run the Project Locally\n\n### Step 1: Clone or Navigate to Project Directory\n```bash\ncd house-price-prediction\n```\n\n### Step 2: Create and Activate a Python Virtual Environment\n```bash\n# macOS/Linux\npython3 -m venv venv\nsource venv/bin/activate\n\n# Windows\npython -m venv venv\nvenv\\Scripts\\activate\n```\n\n### Step 3: Install Required Dependencies\n```bash\npip install -r requirements.txt\n```\n\n### Step 4: Run the Streamlit Application\n```bash\nstreamlit run app.py\n```\nThe application will launch in your default web browser at `http://localhost:8501`.\n\n---\n\n## \ud83d\udcc2 Project Structure\n```\n\u251c\u2500\u2500 app.py                      # Main Streamlit web application & ML pipeline\n\u251c\u2500\u2500 house_prices.csv            # 650-row real estate dataset\n\u251c\u2500\u2500 requirements.txt            # Python library dependencies\n\u251c\u2500\u2500 README.md                   # Setup guide and technical documentation\n\u251c\u2500\u2500 project_documentation.md    # 29-section College Major Project Report\n\u251c\u2500\u2500 viva_questions.md           # 25+ Viva questions & model answers\n```\n\n---\n\n## \ud83d\udcca Machine Learning Pipeline Workflow\n```\n[ house_prices.csv ]\n        \u2502\n        \u25bc\n[ Data Preprocessing ] \u2500\u2500> Null Check & Median Imputation, Duplicate Removal\n        \u2502\n        \u25bc\n[ Train/Test Split ] \u2500\u2500\u2500\u2500> 80% Training Data / 20% Testing Data\n        \u2502\n        \u25bc\n[ Feature Scaling ] \u2500\u2500\u2500\u2500\u2500> StandardScaler (Z-Score Normalization)\n        \u2502\n        \u25bc\n[ Model Fitting ] \u2500\u2500\u2500\u2500\u2500\u2500\u2500> Ordinary Least Squares (OLS) Closed-Form Solution\n        \u2502\n        \u25bc\n[ Model Evaluation ] \u2500\u2500\u2500\u2500> MSE, RMSE, MAE, R\u00b2 Score, Residual Analysis\n        \u2502\n        \u25bc\n[ User Interface ] \u2500\u2500\u2500\u2500\u2500\u2500> User Inputs Property Specs \u2500\u2500> Predicted Price (\u20b9)\n```\n\n---\n\n## \ud83d\udcc8 Evaluation Metrics\n- **Mean Squared Error (MSE):** Measures the average squared difference between estimated values and actual prices.\n- **Root Mean Squared Error (RMSE):** Represents standard deviation of the residuals in Indian Rupees (\u20b9).\n- **R\u00b2 Score (Coefficient of Determination):** Explains >90% of price variance based on selected features.\n\n---\n\n## \ud83d\udcc4 License & Attribution\nDeveloped as an academic major project for academic demonstration and machine learning research.\n";
export const PROJECT_DOC_CODE = "# COLLEGE MAJOR PROJECT DOCUMENTATION\n# Title: HOUSE PRICE PREDICTION USING LINEAR REGRESSION\n\n---\n\n### 1. Project Title\n**HOUSE PRICE PREDICTION USING LINEAR REGRESSION**\n\n### 2. Abstract\nThe real estate market is one of the most volatile and significant sectors of the modern economy. Accurate pricing of houses is crucial for home buyers, property investors, financial institutions, and real estate developers. Traditionally, property valuation relies on human appraisers, historical sales records, or subjective broker intuition, often leading to price distortions and market friction. This major project proposes an automated, data-driven machine learning system utilizing the **Multiple Linear Regression** algorithm. The model learns statistical relationships between property attributes (such as built-up area in square feet, number of bedrooms, bathrooms, floors, parking spaces, age of construction, locality score, and proximity to the city center) and property market price. The system is deployed as an interactive web dashboard providing real-time data inspection, statistical visualizations, model evaluation metrics (MSE, RMSE, R\u00b2 Score), and instantaneous house price estimation in Indian Rupees (\u20b9).\n\n### 3. Introduction\nMachine learning has emerged as an indispensable paradigm in real estate analytics. Regression analysis, in particular, is a foundational supervised learning methodology aimed at predicting a continuous numerical target variable based on one or more explanatory predictor variables. This project focuses on solving the real estate valuation problem using Multiple Linear Regression. Through an end-to-end pipeline encompassing data ingestion, cleaning, exploratory data analysis (EDA), standardization, model training, and web deployment, this project demonstrates how machine learning brings transparency and accuracy to property valuation.\n\n### 4. Problem Statement\nTraditional house price estimation suffers from several severe problems:\n1. **Subjective Bias:** Real estate brokers frequently artificially inflate or deflate rates based on personal commissions.\n2. **Lack of Transparency:** Buyers and sellers lack access to empirical models demonstrating which property features account for price variations.\n3. **Inefficiency:** Manual appraisals are time-consuming and expensive.\n4. **Information Asymmetry:** First-time home buyers are easily misled without quantitative benchmark data.\n\nThere is a distinct need for an objective, mathematical, and automated software tool that computes transparent house valuations based on physical and geographic attributes.\n\n### 5. Aim\nTo develop, train, evaluate, and deploy an automated machine learning web application using Multiple Linear Regression that predicts the monetary price of residential houses from physical and location-based features.\n\n### 6. Objectives\n- To gather and sanitize a representative residential property dataset (`house_prices.csv`).\n- To conduct Exploratory Data Analysis (EDA) uncovering statistical correlations and distribution patterns.\n- To implement data preprocessing pipelines including duplicate removal, missing value imputation, and feature standardization.\n- To train a Multiple Linear Regression model using scikit-learn via Ordinary Least Squares (OLS).\n- To evaluate model performance using standard metrics: Mean Squared Error (MSE), Root Mean Squared Error (RMSE), Mean Absolute Error (MAE), and R\u00b2 Score.\n- To build a clean, responsive, and intuitive web user interface allowing users to input house specifications and receive real-time price predictions in Indian Rupees (\u20b9).\n\n### 7. Existing System\nIn the existing conventional system:\n- Valuation is conducted via physical inspection by government or private property appraisers.\n- Estimates are largely based on local word-of-mouth or recent registry transactions in the same neighborhood without controlling for property-specific parameters like age, parking, or layout.\n- Process takes days or weeks and costs significant appraisal fees.\n- Estimates vary dramatically between different appraisers.\n\n### 8. Proposed System\nThe proposed system automates property valuation using Machine Learning:\n- Utilizes Ordinary Least Squares (OLS) Multiple Linear Regression to model property prices mathematically.\n- Ingests multiple independent features simultaneously (area, rooms, floors, age, distance, locality score).\n- Provides instant, repeatable, deterministic valuations with zero manual delay.\n- Transparently exposes feature coefficients, explaining exactly how much each additional square foot or bedroom contributes to the total price.\n- Offers interactive visualizations and diagnostic charts for model verification.\n\n### 9. Scope of the Project\n- **Academic Scope:** Demonstrates core principles of Supervised Machine Learning, statistical linear modeling, data preprocessing pipelines, and web framework integration for BCA/B.Tech students.\n- **Functional Scope:** Applicable for property buyers, sellers, mortgage loan officers, and real estate portals to establish baseline price benchmarks.\n- **Future Expansion:** The architecture can readily ingest additional geographic parameters (crime rates, school ratings) or advanced algorithms (Random Forests, Gradient Boosting).\n\n### 10. Literature / Background\nLinear regression was first formally developed by Carl Friedrich Gauss and Adrien-Marie Legendre in the early 19th century through the method of least squares to predict planetary orbits. In modern predictive modeling and econometrics, Hedonic Pricing Models (Rosen, 1974) establish that goods are valued for their utility-bearing characteristics. In real estate, hedonic regression models house price as a linear combination of its intrinsic features (structural qualities) and extrinsic features (neighborhood and locational amenities).\n\n### 11. Technologies Used\n- **Programming Language:** Python 3.10+\n- **Machine Learning Library:** `scikit-learn`\n- **Numerical Computation:** `numpy`\n- **Data Manipulation:** `pandas`\n- **Data Visualization:** `matplotlib`, `seaborn`\n- **User Interface Framework:** `Streamlit` / React SPA with Tailwind CSS\n- **Data Format:** CSV (Comma-Separated Values)\n\n### 12. Hardware Requirements\n- **Processor:** Intel Core i3 / AMD Ryzen 3 or higher\n- **RAM:** Minimum 4 GB (8 GB recommended)\n- **Hard Disk:** 500 MB free storage\n- **Display:** 1024x768 minimum resolution screen\n\n### 13. Software Requirements\n- **Operating System:** Windows 10/11, macOS, or Linux (Ubuntu)\n- **Python Environment:** Python 3.10+ with `pip`\n- **Code Editor / IDE:** VS Code, PyCharm, or Jupyter Notebook\n- **Modern Web Browser:** Google Chrome, Mozilla Firefox, or Microsoft Edge\n\n### 14. Dataset Description\nThe dataset (`house_prices.csv`) contains 650 records of residential housing units with 8 input features and 1 continuous target variable:\n1. `Area_sqft` (Numeric, Continuous): Carpet and built-up area in square feet (500 - 5,000 sqft).\n2. `Bedrooms` (Numeric, Discrete): Number of bedrooms (1 to 6).\n3. `Bathrooms` (Numeric, Discrete): Number of bathrooms (1 to 5).\n4. `Floors` (Numeric, Discrete): Number of stories (1 to 4).\n5. `Parking` (Numeric, Discrete): Reserved vehicle parking spaces (0 to 3).\n6. `Age` (Numeric, Continuous): Age of property construction in years (0 to 35).\n7. `Location_Score` (Numeric, Continuous): Locality and infrastructure rating from 1.0 (basic) to 10.0 (prime).\n8. `Distance_to_City_km` (Numeric, Continuous): Distance from central business district in km (1.0 to 35.0 km).\n9. `House_Price` (Numeric, Continuous, Target): Total valuation of the house in Indian Rupees (\u20b9).\n\n### 15. Data Preprocessing\n- **Duplicate Removal:** Identifies and eliminates redundant rows using `.drop_duplicates()`.\n- **Missing Value Handling:** Missing continuous numerical values are imputed using feature medians to maintain robustness against outliers.\n- **Outlier Inspection:** Interquartile Range (IQR) checks ensure values stay within realistic property constraints.\n- **Feature Standardization:** Employs `StandardScaler` to transform features to have zero mean and unit variance ($z = \\frac{x - \\mu}{\\sigma}$), ensuring balanced gradient updates and coefficient stability.\n\n### 16. Exploratory Data Analysis (EDA)\nEDA steps implemented:\n- **Univariate Analysis:** Distribution histograms and Kernel Density Estimation (KDE) plots to examine normality of `House_Price` and `Area_sqft`.\n- **Bivariate Analysis:** Scatter plots with OLS regression lines for `Area_sqft` vs `House_Price`.\n- **Categorical Breakdown:** Box plots showing price spread across bedroom numbers.\n- **Multivariate Correlation:** Pearson Correlation Heatmap measuring pairwise linear associations between all features.\n\n### 17. Feature Selection\nAll 8 features exhibit meaningful physical and statistical correlation with `House_Price`:\n- High positive correlation: `Area_sqft` (~0.85), `Location_Score` (~0.45), `Bedrooms` (~0.60).\n- Negative correlation: `Distance_to_City_km` (~ -0.35), `Age` (~ -0.25).\n- Multicollinearity between bedrooms and area is recognized and moderated via standard scaling.\n\n### 18. Linear Regression Algorithm\nMultiple Linear Regression assumes a linear relationship between input vector $\\mathbf{X}$ and target $Y$:\n$$Y = \\beta_0 + \\beta_1 X_1 + \\beta_2 X_2 + \\dots + \\beta_n X_n + \\epsilon$$\nIn matrix notation:\n$$\\mathbf{y} = \\mathbf{X}\\boldsymbol{\\beta} + \\boldsymbol{\\epsilon}$$\nThe Ordinary Least Squares (OLS) objective minimizes the Residual Sum of Squares (RSS):\n$$\\text{RSS}(\\boldsymbol{\\beta}) = \\sum_{i=1}^{m} (y_i - \\hat{y}_i)^2 = (\\mathbf{y} - \\mathbf{X}\\boldsymbol{\\beta})^T(\\mathbf{y} - \\mathbf{X}\\boldsymbol{\\beta})$$\nSetting the gradient to zero yields the closed-form Normal Equation:\n$$\\boldsymbol{\\beta} = (\\mathbf{X}^T \\mathbf{X})^{-1} \\mathbf{X}^T \\mathbf{y}$$\n\n### 19. Model Training\nThe dataset is partitioned into 80% Training Set (520 records) and 20% Testing Set (130 records) with a fixed random seed for reproducibility. The scikit-learn `Pipeline` scales training data and computes optimal weights $\\boldsymbol{\\beta}$ via OLS.\n\n### 20. Model Evaluation\nThe trained model is evaluated on the unseen testing dataset using:\n- **Mean Squared Error (MSE):** $\\frac{1}{n} \\sum_{i=1}^{n} (y_i - \\hat{y}_i)^2$\n- **Root Mean Squared Error (RMSE):** $\\sqrt{\\text{MSE}}$\n- **Mean Absolute Error (MAE):** $\\frac{1}{n} \\sum_{i=1}^{n} |y_i - \\hat{y}_i|$\n- **R\u00b2 Score (Coefficient of Determination):**\n  $$R^2 = 1 - \\frac{\\sum (y_i - \\hat{y}_i)^2}{\\sum (y_i - \\bar{y})^2}$$\nThe model consistently achieves an $R^2$ score $> 0.90$, indicating that over 90% of the variance in house prices is captured by the regression model.\n\n### 21. System Architecture\n```\n+-------------------------------------------------------------+\n|                      USER INTERFACE                         |\n|  (Streamlit / Web Dashboard: Inputs, Charts & Predictions)  |\n+-------------------------------------------------------------+\n                              \u25b2\n                              \u2502\n+-------------------------------------------------------------+\n|                PREDICTION & INFERENCE ENGINE                |\n|           Pipeline.predict() -> Formatted \u20b9 Result          |\n+-------------------------------------------------------------+\n                              \u25b2\n                              \u2502\n+-------------------------------------------------------------+\n|                 LINEAR REGRESSION MODEL                     |\n|         Trained Weights (Coefficients + Intercept)          |\n+-------------------------------------------------------------+\n                              \u25b2\n                              \u2502\n+-------------------------------------------------------------+\n|                   PREPROCESSING PIPELINE                    |\n|        StandardScaler + Train-Test Split (80/20)            |\n+-------------------------------------------------------------+\n                              \u25b2\n                              \u2502\n+-------------------------------------------------------------+\n|                      DATASET LAYER                          |\n|             house_prices.csv (650 Records)                  |\n+-------------------------------------------------------------+\n```\n\n### 22. Modules Description\n- **Module 1 \u2013 Dataset Collection:** Reads and parses `house_prices.csv` into memory using Pandas.\n- **Module 2 \u2013 Data Preprocessing:** Removes duplicates, handles null values via median imputation, and standardizes continuous features.\n- **Module 3 \u2013 Exploratory Data Analysis:** Generates price distribution plots, scatter diagrams with trendlines, boxplots, and correlation heatmaps.\n- **Module 4 \u2013 Feature Selection:** Separates the 8 predictor features from the continuous target variable `House_Price`.\n- **Module 5 \u2013 Linear Regression Model:** Configures the scikit-learn Pipeline with `StandardScaler` and `LinearRegression`.\n- **Module 6 \u2013 Model Training:** Fits the model on 80% training data using closed-form OLS optimization.\n- **Module 7 \u2013 Model Evaluation:** Evaluates testing holdout on MSE, RMSE, MAE, R\u00b2 score, and generates Actual vs Predicted plots.\n- **Module 8 \u2013 House Price Prediction:** Accepts user input values from the UI, applies identical pipeline scaling, and predicts the estimated house price.\n- **Module 9 \u2013 Visualization and Dashboard:** Delivers a responsive dashboard with navigation menus, metrics cards, and breakdown tables.\n\n### 23. Working Methodology\n1. **System Ingestion:** System loads dataset from disk upon startup.\n2. **Preprocessing:** Pipeline checks schema, types, and values.\n3. **Training & Validation:** Model calculates coefficients and metrics on holdout test partition.\n4. **User Interaction:** User specifies area, bedrooms, bathrooms, floors, parking, age, location score, and distance.\n5. **Prediction Generation:** Input features are transformed using training scale parameters and passed to the regression equation.\n6. **Result Display:** Estimated price is formatted in Indian Rupee notation (\u20b9XX,XX,XXX) alongside an itemized feature contribution breakdown.\n\n### 24. Step-by-Step Algorithm\n1. **Step 1:** Ingest dataset $D = \\{(\\mathbf{x}_1, y_1), \\dots, (\\mathbf{x}_m, y_m)\\}$.\n2. **Step 2:** Sanitize $D$ by removing duplicate rows and filling missing cells with column medians.\n3. **Step 3:** Separate independent matrix $\\mathbf{X}$ and target vector $\\mathbf{y}$.\n4. **Step 4:** Split into $(\\mathbf{X}_{\\text{train}}, \\mathbf{y}_{\\text{train}})$ and $(\\mathbf{X}_{\\text{test}}, \\mathbf{y}_{\\text{test}})$ using ratio 80:20.\n5. **Step 5:** Compute sample mean $\\boldsymbol{\\mu}$ and standard deviation $\\boldsymbol{\\sigma}$ on $\\mathbf{X}_{\\text{train}}$ for scaling.\n6. **Step 6:** Compute normal equation $\\boldsymbol{\\beta} = (\\mathbf{X}_{\\text{train}}^T \\mathbf{X}_{\\text{train}})^{-1} \\mathbf{X}_{\\text{train}}^T \\mathbf{y}_{\\text{train}}$.\n7. **Step 7:** Predict test values $\\hat{\\mathbf{y}}_{\\text{test}} = \\mathbf{X}_{\\text{test}} \\boldsymbol{\\beta}$.\n8. **Step 8:** Calculate evaluation metrics $MSE$ and $R^2$.\n9. **Step 9:** Accept user test input $\\mathbf{x}_{\\text{user}}$.\n10. **Step 10:** Scale $\\mathbf{x}_{\\text{user, scaled}} = \\frac{\\mathbf{x}_{\\text{user}} - \\boldsymbol{\\mu}}{\\boldsymbol{\\sigma}}$.\n11. **Step 11:** Compute $\\hat{y} = \\beta_0 + \\sum_{j=1}^8 \\beta_j x_{\\text{user, scaled}, j}$.\n12. **Step 12:** Display formatted price in Indian currency format.\n\n### 25. Advantages\n- **Fast Execution:** Linear regression has minimal computational complexity and provides instantaneous predictions.\n- **High Interpretability:** Every coefficient directly represents the marginal monetary value of that feature.\n- **No Black-Box Obscurity:** Transparent calculations make it ideal for financial justification and academic evaluation.\n- **Robust Baseline:** Serves as the gold-standard benchmark model in real estate econometric literature.\n\n### 26. Limitations\n- **Linearity Assumption:** Assumes strictly additive linear feature interactions; non-linear inflection points (e.g., luxury estate premiums) require polynomial terms.\n- **Outlier Sensitivity:** OLS minimizes squared error terms, making it sensitive to uncharacteristic extreme luxury properties.\n- **Locality Constraints:** A single global linear model cannot capture highly localized neighborhood micro-markets without geospatial features.\n\n### 27. Future Enhancements\n- **Non-Linear Ensembles:** Incorporating Random Forest and XGBoost regressors for comparison.\n- **Interactive Mapping:** Integrating Google Maps or OpenStreetMap for pin-drop location selection.\n- **Image Valuation:** Utilizing deep learning (CNNs) to score property finish and condition from interior photos.\n- **Mortgage & EMI Calculator:** Adding an integrated loan amortization and EMI calculator based on predicted price.\n\n### 28. Expected Results\n- High prediction accuracy with $R^2 \\ge 0.90$.\n- Clear visual correlation between square footage, location score, and house price.\n- Seamless user experience with instantaneous price estimation and detailed contribution breakdown.\n\n### 29. Conclusion\nThe \"House Price Prediction Using Linear Regression\" project successfully applies supervised machine learning to solve an important practical problem. By structuring the solution through a disciplined engineering pipeline\u2014from data preprocessing and EDA to mathematical model fitting and web deployment\u2014the project provides an accessible, transparent, and accurate pricing estimation tool suitable for both academic demonstration and real-world benchmarking.\n";
export const VIVA_QUESTIONS_CODE = "# \ud83c\udf93 VIVA VOCE QUESTIONS & ANSWERS\n## Project: HOUSE PRICE PREDICTION USING LINEAR REGRESSION\n### For BCA / B.Sc / B.Tech Computer Science Major Project Examination\n\n---\n\n### Q1: What is Machine Learning?\n**Answer:** Machine Learning is a branch of Artificial Intelligence (AI) that enables computer systems to learn patterns and relationships directly from empirical data without being explicitly programmed with hardcoded rules.\n\n### Q2: What is Supervised Learning?\n**Answer:** Supervised Learning is a category of machine learning where the model is trained on labeled data containing both input features ($X$) and ground-truth output labels ($y$). The model learns a mathematical mapping function $y = f(X)$ so that it can predict labels for new, unseen input data.\n\n### Q3: What is Regression in Machine Learning?\n**Answer:** Regression is a supervised learning task where the target output variable is a continuous numerical value (such as price, temperature, or height), in contrast to Classification where the target is a discrete categorical label (such as Spam/Not Spam).\n\n### Q4: What is Linear Regression?\n**Answer:** Linear Regression is a statistical and machine learning technique that models the linear relationship between one or more independent predictor variables ($X$) and a continuous dependent target variable ($y$) using a straight-line equation:\n$$y = \\beta_0 + \\beta_1 X_1 + \\beta_2 X_2 + \\dots + \\beta_n X_n + \\epsilon$$\n\n### Q5: Why is Linear Regression suitable for this house price prediction project?\n**Answer:**\n1. House prices naturally exhibit a strong direct linear relationship with attributes like square footage, bedrooms, and location score.\n2. It offers high interpretability: each coefficient provides a direct monetary value (e.g., adding 1 sqft adds ~\u20b93,200).\n3. It is computationally lightweight, training in milliseconds with closed-form mathematical guarantees (OLS).\n4. It provides an ideal academic benchmark for major project evaluation.\n\n### Q6: What is a Dependent Variable?\n**Answer:** The dependent variable (also called the target or response variable) is the outcome being predicted by the model. In this project, **`House_Price`** is the dependent variable because its value depends upon property characteristics.\n\n### Q7: What are Independent Variables?\n**Answer:** Independent variables (also called input features or predictor variables) are the attributes used by the model to calculate the prediction. In this project, the 8 independent variables are:\n`Area_sqft`, `Bedrooms`, `Bathrooms`, `Floors`, `Parking`, `Age`, `Location_Score`, and `Distance_to_City_km`.\n\n### Q8: What is train_test_split?\n**Answer:** `train_test_split` is a function from scikit-learn's `model_selection` module that randomly partitions a dataset into two subsets:\n1. **Training Set (typically 70% - 80%):** Used by the algorithm to learn weights/coefficients.\n2. **Testing Set (typically 20% - 30%):** Held out as unseen data to evaluate how accurately the model generalizes.\n\n### Q9: Why do we split the dataset into train and test sets?\n**Answer:** If we evaluate the model on the same data it was trained on, we cannot verify whether it actually learned generalizable patterns or simply memorized the data (overfitting). Splitting data ensures an unbiased, realistic measurement of model performance on fresh real-world inputs.\n\n### Q10: What is Data Preprocessing?\n**Answer:** Data preprocessing is the process of cleaning, transforming, and organizing raw data into an orderly format suitable for training machine learning algorithms. It includes handling missing values, eliminating duplicate records, removing outliers, and scaling features.\n\n### Q11: What is Feature Scaling and why is it used?\n**Answer:** Feature scaling (e.g., `StandardScaler`) transforms numerical features that have vastly different ranges (like `Area_sqft` in thousands vs `Floors` from 1 to 4) into a comparable numerical scale (mean = 0, standard deviation = 1). This prevents high-magnitude features from dominating the gradient calculations and ensures numerical stability.\n\n### Q12: What is Mean Squared Error (MSE)?\n**Answer:** MSE is a loss and evaluation metric that measures the average of the squared differences between the actual house prices ($y$) and the predicted prices ($\\hat{y}$):\n$$\\text{MSE} = \\frac{1}{n} \\sum_{i=1}^{n} (y_i - \\hat{y}_i)^2$$\nBecause errors are squared, MSE heavily penalizes large estimation errors.\n\n### Q13: What is Root Mean Squared Error (RMSE)?\n**Answer:** RMSE is simply the square root of MSE ($\\sqrt{\\text{MSE}}$). The primary advantage of RMSE is that it is expressed in the same physical units as the target variable (in this case, in Indian Rupees \u20b9), making it intuitive to interpret as the average pricing error.\n\n### Q14: What is R\u00b2 Score (Coefficient of Determination)?\n**Answer:** $R^2$ is a statistical metric ranging from 0 to 1 (or 0% to 100%) that measures the proportion of variance in the target variable that is explained by the input features in the model:\n$$R^2 = 1 - \\frac{\\text{SS}_{\\text{residual}}}{\\text{SS}_{\\text{total}}}$$\nAn $R^2$ of 0.92 means 92% of the variation in house prices is captured by our features.\n\n### Q15: What does a Regression Coefficient ($\\beta_i$) mean?\n**Answer:** A regression coefficient represents the rate of change in the target variable for every 1-unit increase in that specific feature, holding all other features constant. For example, if the coefficient of `Area_sqft` is 3,200, an increase of 1 square foot raises the predicted house price by \u20b93,200.\n\n### Q16: What is an Intercept ($\\beta_0$)?\n**Answer:** The intercept represents the expected baseline value of the dependent variable when all input features are zero ($X_1 = X_2 = \\dots = 0$).\n\n### Q17: What is Overfitting?\n**Answer:** Overfitting occurs when a machine learning model learns the training data and its random noise too closely, achieving near-perfect scores on the training set but failing to generalize and performing poorly on unseen testing data.\n\n### Q18: What is Underfitting?\n**Answer:** Underfitting occurs when a model is overly simplistic and cannot capture the underlying trend in the data, resulting in poor accuracy on both the training set and testing set.\n\n### Q19: What is Ordinary Least Squares (OLS)?\n**Answer:** OLS is the mathematical optimization technique used by scikit-learn's `LinearRegression`. It finds the optimal coefficient vector $\\boldsymbol{\\beta}$ by minimizing the sum of squared vertical distances (residuals) between observed data points and the fitted regression hyperplane:\n$$\\boldsymbol{\\beta} = (\\mathbf{X}^T \\mathbf{X})^{-1} \\mathbf{X}^T \\mathbf{y}$$\n\n### Q20: What are the main limitations of Linear Regression?\n**Answer:**\n1. It assumes a purely linear relationship between features and the target.\n2. It is sensitive to extreme outliers due to squared error penalties.\n3. It assumes features are independent (can suffer from multicollinearity).\n\n### Q21: Why is house price considered a continuous target variable?\n**Answer:** A house price is continuous because it can take any real numerical value along an unbroken continuum (e.g., \u20b945,50,000, \u20b945,50,500, etc.), unlike discrete classes which have predefined discrete categories.\n\n### Q22: What happens when the user clicks 'PREDICT HOUSE PRICE' in the application?\n**Answer:**\n1. The user's input values from the input fields/sliders are collected into a Pandas DataFrame.\n2. The values pass through the fitted `StandardScaler` pipeline to normalize them to the exact distribution scale learned during training.\n3. The scaled values are multiplied by the model's coefficients $\\boldsymbol{\\beta}$ and added to the intercept $\\beta_0$.\n4. The resulting estimated price is formatted in Indian Rupee currency notation (\u20b9XX,XX,XXX) and displayed on the UI alongside an itemized feature contribution breakdown.\n\n### Q23: Why must the exact same preprocessing pipeline be applied to user predictions as training?\n**Answer:** If the model was trained on scaled numbers (e.g., mean 0, std 1), feeding it raw numbers (like 2,000 sqft) would produce completely invalid mathematical outputs. A scikit-learn `Pipeline` guarantees consistency by applying the exact same scaling parameters ($\\mu, \\sigma$) learned during training to new user inputs.\n\n### Q24: What is the purpose of the Correlation Matrix / Heatmap in EDA?\n**Answer:** The correlation heatmap visualizes Pearson correlation coefficients between every pair of features. It helps identify which features have the strongest positive or negative correlation with house price, and helps detect potential multicollinearity between predictor features (like area and number of rooms).\n\n### Q25: How can this project be enhanced in the future?\n**Answer:**\n1. Implementing non-linear algorithms such as Random Forest Regressor and XGBoost.\n2. Integrating interactive Google Maps or OpenStreetMap for automatic coordinate-based amenity scoring.\n3. Connecting a real-time database to ingest live real estate listings.\n4. Adding deep learning computer vision to evaluate interior and exterior photos of the house.\n";
